faroInitPromise &&= Promise.all([import('@grafana/faro-web-sdk'), import('@grafana/faro-web-tracing')]).then(([{
  initializeFaro,
  getWebInstrumentations
}, {
  TracingInstrumentation
}]) => {
  faro = initializeFaro({
    url: config.url,
    app: {
      name: config.appName,
      version: config.appVersion,
      environment: config.environment
    },
    instrumentations: [...getWebInstrumentations(), new TracingInstrumentation({
      instrumentationOptions: {
        // Stitch FE traces onto BE traces: propagate `traceparent` to the API origin.
        propagateTraceHeaderCorsUrls: [originToRegExp(config.apiOrigin)]
      }
    })]
  });
  faroReady.value = true;
  logger.debug('observability', '[Faro] Initialized', config.environment, '→', config.url);
  return true;
})

