import { computed, ref } from 'vue';
import { defineStore } from 'pinia';
import { useCoreStore, useStructureRestApi } from '@guebbit/vue-toolkit';
import { getWishlist, addWishlistItem, removeWishlistItem, moveWishlistItemToCart } from '@api';
import type { WishlistItem } from '@types';
import { useCartStore } from '@/modules/cart';
import { useObservabilityStore, analyticsEvents } from '@/infrastructure/observability';

/**
 * The visitor's saved products — ids only, like the cart's lines: the view joins them against
 * whatever product data it holds, and every action replaces the local list with the payload the
 * API answered with.
 *
 * Depends on cart for exactly one thing: move-to-cart changes the cart server-side, and the
 * header's badge must not lag behind a write this store initiated.
 */
export const useWishlistStore = defineStore('wishlist', () => {
    const { getLoading, setLoading } = useCoreStore();
    const { loading, fetchAny } = useStructureRestApi<WishlistItem, string>({
        getLoading,
        setLoading
    });

    /** The saved lines. */
    const items = ref<WishlistItem[]>([]);

    /** Saved product ids, for O(1) "is this saved" reads. */
    const savedProductIds = computed(() => new Set(items.value.map(({ productId }) => productId)));

    /**
     * Whether one product is saved — what a heart icon reads.
     *
     * @param productId - The product in question.
     * @returns `true` when it is on the wishlist.
     */
    const isSaved = (productId: string) => savedProductIds.value.has(productId);

    /**
     * Loads the wishlist.
     *
     * @returns A promise resolving with the saved lines.
     */
    const fetchWishlist = () =>
        fetchAny(() =>
            getWishlist().then((response) => {
                items.value = response.data?.items ?? [];
                return items.value;
            })
        );

    /**
     * Saves a product. Idempotent server-side, so a double-clicked heart answers the same list.
     *
     * @param productId - The product to save.
     * @returns A promise resolving with the updated lines.
     */
    const addToWishlist = (productId: string) =>
        fetchAny(() =>
            addWishlistItem({ productId }).then((response) => {
                const obs = useObservabilityStore();
                obs.track(analyticsEvents.WISHLIST_ITEM_ADDED, { product_id: productId });
                items.value = response.data?.items ?? [];
                return items.value;
            })
        );

    /**
     * Removes a saved product.
     *
     * @param productId - The product to unsave.
     * @returns A promise resolving with the updated lines.
     */
    const removeFromWishlist = (productId: string) =>
        fetchAny(() =>
            removeWishlistItem(productId).then((response) => {
                const obs = useObservabilityStore();
                obs.track(analyticsEvents.WISHLIST_ITEM_REMOVED, { product_id: productId });
                items.value = response.data?.items ?? [];
                return items.value;
            })
        );

    /**
     * The wishlist's exit: the saved line becomes a cart line server-side, so afterwards the
     * cart is refetched rather than guessed at — the cart store never invents a payload the API
     * did not send, and neither does this one on its behalf.
     *
     * @param productId - The saved product to move.
     * @returns A promise resolving with the updated saved lines.
     */
    const moveToCart = (productId: string) =>
        fetchAny(() =>
            moveWishlistItemToCart(productId).then((response) => {
                const obs = useObservabilityStore();
                obs.track(analyticsEvents.WISHLIST_MOVED_TO_CART, { product_id: productId });
                items.value = response.data?.items ?? [];
                return useCartStore()
                    .fetchCart()
                    .then(() => items.value);
            })
        );

    return {
        items,
        savedProductIds,
        isSaved,

        loading,
        fetchWishlist,
        addToWishlist,
        removeFromWishlist,
        moveToCart
    };
});

src/modules/admin/composables/useAdminOb.source:
import { computed, type ComputedRef, type Ref } from 'vue';
import {
    getObservabilityHealth,
    getObservabilityMetricsOverview,
    getObservabilityAuditLogs
} from '@api';
import type { ObservabilityHealth, ObservabilityMetricsSummary, AuditEventItem } from '@types';
import type { IAdminAuditFilters } from '@/modules/admin/types.ts';
import { useAsyncAction } from '@/infrastructure/useAsyncAction.ts';

export interface IUseAdminObservabilityReturn {
    health: Ref<ObservabilityHealth | undefined>;
    metrics: Ref<ObservabilityMetricsSummary | undefined>;
    auditEvents: ComputedRef<AuditEventItem[]>;
    auditTotal: ComputedRef<number>;
    loadingHealth: Ref<boolean>;
    loadingMetrics: Ref<boolean>;
    loadingAudit: Ref<boolean>;
    errorHealth: Ref<string | undefined>;
    errorMetrics: Ref<string | undefined>;
    errorAudit: Ref<string | undefined>;
    fetchHealth: () => Promise<void>;
    fetchMetrics: () => Promise<void>;
    fetchAuditLogs: (filters?: IAdminAuditFilters) => Promise<void>;
    fetchAll: () => Promise<void>;
}

/**
 * Unified composable for the Admin observability dashboard.
 *
 * It exposes the three contract-backed endpoints behind one shared state:
 * - GET /observability/health
 * - GET /observability/metrics/overview
 * - GET /observability/audit
 *
 * Each is a {@link useAsyncAction}: the loading/data/error bookkeeping is written once there
 * rather than three times here, and every fetcher resolves rather than rejects, so a partially
 * available stack still renders the panels that answered.
 *
 * @returns Shared state (payloads, per-call loading flags and error messages) plus the four
 *  fetchers.
 */
export const useAdminObservability = (): IUseAdminObservabilityReturn => {
    const {
        data: health,
        error: errorHealth,
        loading: loadingHealth,
        run: runHealth
    } = useAsyncAction(() => getObservabilityHealth().then((response) => response.data), {
        fallbackErrorMessage: 'Failed to load health data'
    });

    const {
        data: metrics,
        error: errorMetrics,
        loading: loadingMetrics,
        run: runMetrics
    } = useAsyncAction(() => getObservabilityMetricsOverview().then((response) => response.data), {
        fallbackErrorMessage: 'Failed to load metrics data'
    });

    /**
     * The audit call answers with items AND a total, so its payload is the envelope; the two are
     * split back out below rather than tracked as separate state that could disagree.
     */
    const {
        data: audit,
        error: errorAudit,
        loading: loadingAudit,
        run: runAuditLogs
    } = useAsyncAction(
        (filters: IAdminAuditFilters = {}) =>
            getObservabilityAuditLogs({
                actor: filters.actor,
                action: filters.action,
                outcome: filters.outcome,
                since: filters.since,
                limit: filters.limit
            }).then((response) => response.data),
        { fallbackErrorMessage: 'Failed to load audit logs' }
    );

    const auditEvents = computed(() => audit.value?.items ?? []);
    const auditTotal = computed(() => audit.value?.total ?? 0);

    /**
     * The three fetchers resolve with nothing: every consumer reads the state refs, and a
     * `Promise<void>` is what `AdminAuditTab`'s `onSearch` prop is typed to take.
     *
     * @returns A promise resolving once `health` or `errorHealth` is set.
     */
    const fetchHealth = () => runHealth().then(() => {});

    /**
     * @returns A promise resolving once `metrics` or `errorMetrics` is set.
     */
    const fetchMetrics = () => runMetrics().then(() => {});

    /**
     * Loads the audit log page matching the given filters.
     *
     * @param filters - Actor/action/outcome/since/limit criteria; defaults to no filtering at all.
     * @returns A promise resolving once `auditEvents` + `auditTotal`, or `errorAudit`, are set.
     */
    const fetchAuditLogs = (filters: IAdminAuditFilters = {}) =>
        runAuditLogs(filters).then(() => {});

    /**
     * Loads health, metrics and audit logs in parallel, for the initial dashboard render.
     *
     * @returns A promise resolving once all three calls have settled.
     */
    const fetchAll = () =>
        Promise.all([fetchHealth(), fetchMetrics(), fetchAuditLogs()]).then(() => {});

    return {
        health,
        metrics,
        auditEvents,
        auditTotal,
        loadingHealth,
        loadingMetrics,
        loadingAudit,
        errorHealth,
        errorMetrics,
        errorAudit,
        fetchHealth,
        fetchMetrics,
        fetchAuditLogs,
        fetchAll
    };
};

src/modules/realtime/useRealtimeObservab.source:
import { storeToRefs } from 'pinia';
import { useRealtimeObservabilityStore } from '@/modules/realtime/realtimeObservability';
import { createSseClient } from '@/infrastructure/createSseClient';
import { REALTIME_SSE_EVENT_NAMES } from '@types';

/**
 * Module-level singleton: only one SSE connection is active at a time regardless
 * of how many component instances call the composable.
 */
let activeClient: ReturnType<typeof createSseClient> | undefined;

/**
 * Resolves the SSE endpoint URL.
 *
 * @returns `VITE_API_SSE`, or the local dev server endpoint when unset.
 */
const getSseUrl = () =>
    import.meta.env.VITE_API_SSE ?? 'http://localhost:3000/observability/events';

/**
 * Manages the SSE connection feeding the observability dashboard.
 *
 * Uses a module-level `activeClient` singleton so re-mounting the component does
 * not open duplicate streams.
 *
 * @returns The realtime store refs (status, latest payloads, feed, last error)
 *  plus `connect`/`disconnect` controls.
 */
export const useRealtimeObservability = () => {
    const store = useRealtimeObservabilityStore();

    /**
     * Opens (or replaces) the SSE connection, routing each metrics event to its
     * store action and appending it to the feed.
     *
     * Tears down any existing client first to avoid duplicate streams.
     */
    const connect = () => {
        activeClient?.close();
        store.setStatus('connecting');

        // Create the SSE client and wire each metric event type to its store action
        activeClient = createSseClient(getSseUrl(), REALTIME_SSE_EVENT_NAMES, {
            onOpen: () => store.setStatus('open'),
            onError: () => {
                store.setStatus('error');
                store.setError('SSE connection error');
            },
            onEvent: (eventName, payload) => {
                if (eventName === 'observability.metrics.snapshot') {
                    store.setSnapshot(payload);
                    store.addEntry({
                        id: `snapshot-${payload.timestamp}`,
                        kind: 'snapshot',
                        timestamp: payload.timestamp,
                        payload
                    });
                    return;
                }

                if (eventName === 'observability.metrics.updated') {
                    store.setUpdate(payload);
                    store.addEntry({
                        id: `update-${payload.timestamp}`,
                        kind: 'update',
                        timestamp: payload.timestamp,
                        payload
                    });
                    return;
                }

                store.setHeartbeat(payload);
                store.addEntry({
                    id: `heartbeat-${payload.timestamp}`,
                    kind: 'heartbeat',
                    timestamp: payload.timestamp,
                    payload
                });
            }
        });
    };

    /**
     * Closes the active SSE connection and resets the store status to `closed`.
     * Safe to call even when no connection is open.
     */
    const disconnect = () => {
        activeClient?.close();
        activeClient = undefined;
        store.setStatus('closed');
    };

    return {
        ...storeToRefs(store),
        connect,
        disconnect
    };
};

