/**
 * `FormImageUpload.vue` — the component the plan ranks first by risk.
 *
 * `utils/uploads.ts` (the limits and the predicates) is well tested and now carries property
 * tests too. The component WRAPPING it was not tested at all, and the thing it owns is not
 * validation — it is a **resource**.
 *
 * `URL.createObjectURL` pins the picked blob in memory until `revokeObjectURL` releases it. The
 * component holds the URL in a ref precisely so it can revoke it, and there are three moments
 * where failing to do so leaks a whole image:
 *
 *   1. replacing one pick with another,
 *   2. clearing the field,
 *   3. unmounting while a file is picked.
 *
 * None of the three shows up as a failing assertion anywhere else, and none is visible in the UI
 * — it is a long editing session quietly holding a dozen images. So all three are asserted here
 * against a counted stub, which is the only way to see a revoke that did not happen.
 *
 * The other behaviours worth pinning are the two that a naive implementation gets backwards:
 * `progress === 0` must SHOW the bar (a request that has started and sent nothing) while
 * `undefined` hides it; and an array selection must be collapsed back into the model, because
 * every `imageUpload` field in the contract declares a single file.
 */
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { mount } from '@vue/test-utils';
import FormImageUpload from '@/ui/molecules/FormImageUpload.vue';
import vuetify from '@/ui/vuetify';
import { i18n } from '@/infrastructure/i18n';
import { ACCEPTED_IMAGE_ACCEPT_ATTRIBUTE } from '@/infrastructure/uploads';

/** Object-URL bookkeeping, so a missing revoke is observable. */
const created: string[] = [];
const revoked: string[] = [];

beforeEach(() => {
    created.length = 0;
    revoked.length = 0;
    let counter = 0;
    globalThis.URL.createObjectURL = vi.fn(() => {
        counter += 1;
        const url = `blob:mock/${counter}`;
        created.push(url);
        return url;
    });
    globalThis.URL.revokeObjectURL = vi.fn((url: string) => {
        revoked.push(url);
    });
});

afterEach(() => {
    vi.restoreAllMocks();
});

const makeFile = (name = 'photo.png', type = 'image/png') =>
    new File([new Uint8Array([1, 2, 3])], name, { type });

const mountUpload = (props: Record<string, unknown> = {}) =>
    mount(FormImageUpload, {
        props,
        global: { plugins: [vuetify, i18n] }
    });

describe('FormImageUpload — the object-URL resource', () => {
    it('mints exactly one object URL for a picked file', async () => {
        const wrapper = mountUpload();

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();

        expect(created).toHaveLength(1);
    });

    it('revokes the previous URL when the pick is REPLACED', async () => {
        // The leak that is easiest to miss: clearing is usually handled, replacing is not.
        const wrapper = mountUpload();

        await wrapper.setProps({ modelValue: makeFile('first.png') });
        await wrapper.vm.$nextTick();
        await wrapper.setProps({ modelValue: makeFile('second.png') });
        await wrapper.vm.$nextTick();

        expect(created).toHaveLength(2);
        expect(revoked).toContain(created[0]);
    });

    it('revokes the URL when the field is cleared', async () => {
        const wrapper = mountUpload();

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();
        await wrapper.setProps({ modelValue: undefined });
        await wrapper.vm.$nextTick();

        expect(revoked).toContain(created[0]);
    });

    it('revokes the URL on unmount, rather than leaking it with the component', async () => {
        const wrapper = mountUpload();

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();
        wrapper.unmount();

        expect(revoked).toContain(created[0]);
    });

    it('revokes nothing when nothing was ever picked', () => {
        // `releaseObjectUrl` guards on the ref; without the guard this revokes `undefined`.
        mountUpload().unmount();

        expect(revoked).toHaveLength(0);
    });
});

describe('FormImageUpload — the preview', () => {
    it('shows the existing image while nothing is picked', () => {
        const wrapper = mountUpload({ currentImageUrl: '/images/existing.png' });

        expect(wrapper.find('img').attributes('src')).toBe('/images/existing.png');
    });

    it('prefers the picked file over the existing image', async () => {
        // An edit form must not keep showing the old picture after the user chose a new one.
        const wrapper = mountUpload({ currentImageUrl: '/images/existing.png' });

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('img').attributes('src')).toBe(created[0]);
    });

    it('renders no image at all when there is neither', () => {
        expect(mountUpload().find('img').exists()).toBe(false);
    });

    it('falls back to the existing image again once the pick is cleared', async () => {
        const wrapper = mountUpload({ currentImageUrl: '/images/existing.png' });

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();
        await wrapper.setProps({ modelValue: undefined });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('img').attributes('src')).toBe('/images/existing.png');
    });
});

/*
 * Selected by `data-testid`, never by `.v-progress-linear`: Vuetify's `v-file-input` renders its
 * own progress bar inside the field loader, so the class matches even when this component's bar
 * is absent — a spec written against it passes in both states and asserts nothing.
 */
describe('FormImageUpload — the progress bar', () => {
    it('is hidden while no upload is running', () => {
        expect(mountUpload().find('[data-testid=upload-progress]').exists()).toBe(false);
    });

    it('is SHOWN at zero percent, which is not the same as idle', async () => {
        // The distinction the component exists to make: `undefined` is idle, `0` is a request
        // that has started and sent nothing yet. A truthiness check collapses the two.
        const wrapper = mountUpload({ progress: 0 });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('[data-testid=upload-progress]').exists()).toBe(true);
    });

    it('is shown while an upload is in flight', async () => {
        const wrapper = mountUpload({ progress: 42 });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('[data-testid=upload-progress]').exists()).toBe(true);
    });

    it('rounds a fractional percentage', async () => {
        // Asserted on `aria-valuenow` rather than on the visible label, for two reasons: it is
        // what a screen reader actually announces, and the label is an i18n message whose
        // dictionary is lazily loaded, so in a unit test it renders as the raw key.
        const wrapper = mountUpload({ progress: 42.6 });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('[data-testid=upload-progress]').attributes('aria-valuenow')).toBe(
            '43'
        );
    });

    it('reports the exact percentage when it is already whole', async () => {
        const wrapper = mountUpload({ progress: 42 });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('[data-testid=upload-progress]').attributes('aria-valuenow')).toBe(
            '42'
        );
    });
});

describe('FormImageUpload — the field', () => {
    it('restricts the picker to the types the backend accepts', () => {
        // The picker's filter and the validation rule are both derived from ACCEPTED_IMAGE_TYPES
        // so they cannot disagree; this pins that the derivation actually reaches the DOM.
        expect(mountUpload().find('input[type=file]').attributes('accept')).toBe(
            ACCEPTED_IMAGE_ACCEPT_ATTRIBUTE
        );
    });

    it('surfaces validation errors passed by the form', async () => {
        const wrapper = mountUpload({ errorMessages: ['File is too large'] });
        await wrapper.vm.$nextTick();

        expect(wrapper.text()).toContain('File is too large');
    });

    it('disables the picker while the form is submitting', () => {
        expect(
            mountUpload({ disabled: true }).find('input[type=file]').attributes('disabled')
        ).toBeDefined();
    });

    it('collapses an array selection back to a single file', async () => {
        // Vuetify types VFileInput's model as `File | File[] | null` because one component covers
        // the `multiple` case. Every `imageUpload` field in the contract is a single file, so an
        // array reaching the parent would be a contract violation.
        const wrapper = mountUpload();
        const file = makeFile();

        await wrapper.setProps({ modelValue: [file] as unknown as File });
        await wrapper.vm.$nextTick();

        const emitted = wrapper.emitted('update:modelValue');
        expect(emitted?.at(-1)?.[0]).toBe(file);
    });
});

tests/unit/infrastructure/http/http.spec.source:
import { beforeAll, describe, expect, it, vi } from 'vitest';
import enMessages from '@/locales/en.json';

vi.mock('@/infrastructure/session', () => ({
    useSessionStore: vi.fn(() => ({ accessToken: { value: undefined } }))
}));

vi.mock('pinia', () => ({
    storeToRefs: (store: { accessToken: { value: undefined } }) => store
}));

/**
 * Only `getCurrentLocale` is stubbed. `apiText` is deliberately the REAL one, resolving against
 * the real vue-i18n instance: these assertions are about what a user is shown when the API sent
 * no message of its own, and a stubbed translator would make every language look the same.
 */
vi.mock('@/infrastructure/i18n.ts', async (importOriginal) => ({
    ...(await importOriginal<typeof import('@/infrastructure/i18n.ts')>()),
    getCurrentLocale: vi.fn(() => 'en')
}));

beforeAll(() => import('@/infrastructure/i18n.ts').then(({ loadLocale }) => loadLocale('en')));

const makeAxiosError = (status: number, data: unknown, headers: Record<string, string> = {}) => ({
    response: { status, statusText: 'Error', data, headers },
    message: 'Request failed',
    config: { url: '/test' }
});

describe('onResponseReject', () => {
    it('passes through a standard reject envelope unchanged', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = makeAxiosError(400, {
                success: false,
                message: 'Bad',
                errors: ['field required']
            });
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                success: false,
                message: 'Bad',
                errors: ['field required']
            });
        });
    });

    it('enriches a reject envelope with x-request-id and x-trace-id headers', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = makeAxiosError(
                422,
                { success: false, message: 'Validation', errors: ['name required'] },
                { 'x-request-id': 'req-abc-123', 'x-trace-id': 'trace-xyz-789' }
            );
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                errors: ['name required'],
                requestId: 'req-abc-123',
                traceId: 'trace-xyz-789'
            });
        });
    });

    it('captures x-request-id on a fallback transport error', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = makeAxiosError(
                503,
                {},
                {
                    'x-request-id': 'req-fallback-1'
                }
            );
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                success: false,
                requestId: 'req-fallback-1'
            });
        });
    });

    it('normalizes 401 responses as authentication state errors', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = makeAxiosError(401, {});
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                success: false,
                status: 401,
                message: enMessages['api-errors'].unauthorized,
                errors: [enMessages['api-errors'].unauthorized]
            });
        });
    });

    it('normalizes 403 responses as authorization state errors', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = makeAxiosError(403, {});
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                success: false,
                status: 403,
                message: enMessages['api-errors'].forbidden,
                errors: [enMessages['api-errors'].forbidden]
            });
        });
    });

    it('omits requestId and traceId when headers are absent', () => {
        return import('@/infrastructure/http')
            .then(({ onResponseReject }) => {
                const error = makeAxiosError(500, {});
                return onResponseReject(error as never).catch((error_: unknown) => error_);
            })
            .then((result) => {
                expect(result).not.toHaveProperty('requestId');
                expect(result).not.toHaveProperty('traceId');
            });
    });
});

/**
 * The fallback branch of `onResponseReject` — everything that is *not* a well-formed reject
 * envelope from the API. That covers real transport failures (no response at all), gateway errors
 * from a proxy that never reached the app, and any 4xx the API answers without its envelope.
 *
 * The canonicalised messages matter because they are what a user sees: an axios `statusText` of
 * "" or a raw "Network Error" is not something to put in front of someone, and 5xx detail must
 * not leak server internals into the UI.
 */
describe('onResponseReject — fallback normalisation', () => {
    it('canonicalises any 5xx to a single safe message', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            return expect(onResponseReject(makeAxiosError(503, {}) as never)).rejects.toMatchObject(
                {
                    status: 503,
                    message: enMessages['api-errors']['internal-server-error']
                }
            );
        });
    });

    it('treats exactly 500 as a server error', () =>
        // The `>= 500` boundary. With `> 500` a plain 500 would fall through and surface the raw
        // statusText instead — the single most common server failure, mis-messaged.
        import('@/infrastructure/http').then(({ onResponseReject }) =>
            expect(onResponseReject(makeAxiosError(500, {}) as never)).rejects.toMatchObject({
                message: enMessages['api-errors']['internal-server-error']
            })
        ));

    it('leaves a 4xx below the server range on its own message', () =>
        // The other side of the same boundary: 499 must NOT be canonicalised.
        import('@/infrastructure/http').then(({ onResponseReject }) =>
            expect(onResponseReject(makeAxiosError(499, {}) as never)).rejects.toMatchObject({
                status: 499,
                message: 'Error'
            })
        ));

    it('carries no error items for a status that is neither 401 nor 403', () =>
        // 401/403 get a user-facing item because the UI renders them as a state change; other
        // fallbacks deliberately carry an empty list rather than echoing a transport string.
        import('@/infrastructure/http')
            .then(({ onResponseReject }) =>
                onResponseReject(makeAxiosError(404, {}) as never).catch(
                    (error_: unknown) => error_
                )
            )
            .then((result) => {
                expect((result as { errors: string[] }).errors).toEqual([]);
            }));

    it('falls back to status 500 when there is no response at all', () =>
        // A DNS failure, a refused connection, a CORS block: `error.response` is undefined, and
        // every call site still needs a status to branch on.
        import('@/infrastructure/http').then(({ onResponseReject }) =>
            expect(
                onResponseReject({ message: 'Network Error', config: { url: '/x' } } as never)
            ).rejects.toMatchObject({ success: false, status: 500 })
        ));

    it('prefers statusText over the axios message', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = {
                response: { status: 418, statusText: "I'm a teapot", data: {}, headers: {} },
                message: 'Request failed',
                config: { url: '/x' }
            };
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                message: "I'm a teapot"
            });
        });
    });

    it('falls back to the axios message when statusText is empty', () =>
        // `||`, not `??`: axios sets `statusText` to '' rather than undefined on many adapters,
        // and an empty message would render as a blank error toast.
        import('@/infrastructure/http').then(({ onResponseReject }) =>
            expect(
                onResponseReject({
                    response: { status: 418, statusText: '', data: {}, headers: {} },
                    message: 'Request failed',
                    config: { url: '/x' }
                } as never)
            ).rejects.toMatchObject({ message: 'Request failed' })
        ));

    it('falls back to a generic message when neither is available', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = {
                response: { status: 418, statusText: '', data: {}, headers: {} },
                message: '',
                config: { url: '/x' }
            };
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                message: enMessages['api-errors'].unknown
            });
        });
    });

    it('passes an envelope through even when its errors list is empty', () =>
        // Detection is `hasOwnProperty('errors')`, not truthiness — an API reject that happens to
        // carry no items is still the API's own envelope and must not be re-synthesised.
        import('@/infrastructure/http').then(({ onResponseReject }) =>
            expect(
                onResponseReject(
                    makeAxiosError(422, {
                        success: false,
                        status: 422,
                        message: 'Validation failed',
                        errors: []
                    }) as never
                )
            ).rejects.toMatchObject({ message: 'Validation failed', errors: [] })
        ));
});

