/**
 * This module's fixtures, in both profiles. See `src/modules/products/tests/seeds.spec.ts` for why
 * they are asserted here rather than centrally.
 */
import { beforeAll, describe, expect, it } from 'vitest';
import { buildCartMockSeeds } from '@/modules/cart/mocks/register';
import { mockDatabase } from '@mocks/mockDb.ts';
import { mockDatabaseReady } from '../../../../tests/support/unit/mockDatabaseReady.ts';

beforeAll(mockDatabaseReady);

/**
 * The catalogue slice `mockSeeds.after: ['products']` guarantees at runtime.
 *
 * Read from the assembled `mockDatabase` — built by `mockDatabaseReady()` above, through the real
 * fold — rather than by calling the products builder directly: a sibling module's internals are
 * not this module's to import.
 */
const buildWithCatalogue = async (profile: 'seed' | 'random') => {
    const products = mockDatabase.sampleProducts;
    const { sampleCartItems } = await buildCartMockSeeds({
        profile,
        soFar: { sampleProducts: products }
    });

    return { products, items: sampleCartItems ?? [] };
};

describe('the seed profile', () => {
    it('takes the cart the backend embeds on its seeded user', async () => {
        const { items } = await buildWithCatalogue('seed');

        // Only one seeded user has a cart, and `mockDatabase.sampleCartItems` models a single
        // active session's cart rather than a merge of everyone's.
        expect(items).toHaveLength(2);
        expect(items.every((item) => item.quantity > 0)).toBe(true);
    });
});

describe('the random profile', () => {
    it('draws only from the catalogue actually in the database', async () => {
        const { products, items } = await buildWithCatalogue('random');
        const productIds = new Set(products.map((product) => product.id));

        expect(items.length).toBeGreaterThan(0);
        for (const item of items) expect(productIds.has(item.productId)).toBe(true);
    });
});

describe('without a catalogue', () => {
    it('contributes an empty cart rather than items pointing nowhere', async () => {
        // The state after `rm -rf src/modules/products`.
        const { sampleCartItems } = await buildCartMockSeeds({
            profile: 'random',
            soFar: { sampleProducts: [] }
        });

        expect(sampleCartItems).toEqual([]);
    });
});

src/modules/account/tests/storeFlows.spe.source:
/**
 * The account store's session and profile flows — everything `store.spec.ts` does not cover.
 *
 * That file is about `signup` and the one branch worth pinning there: JSON vs. multipart. This one
 * is about the other twelve actions, which are the ones that move state — a token into the session,
 * a viewer projection into the shell, a cleared cache on the way out.
 *
 * ── What is mocked, and what deliberately is not ─────────────────────────────────────────────
 * Only the transport. `orvalMutator` is replaced with a router keyed on the request URL, so every
 * layer above it is the real one: the generated `@api` client, `session.ts`, the observability
 * store, and the `useStructureRestApi` composable that owns `selectedIdentifier` and the cache.
 *
 * That matters because most of these actions are COORDINATION rather than computation — `login`
 * does not transform anything, it puts a token somewhere and then asks for a profile. Mocking the
 * session store would leave nothing under test but the order of two calls into a double. Asserting
 * against the real session store asserts the thing the router guards actually read.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useAccountStore } from '@/modules/account/store.ts';
import { useSessionStore } from '@/infrastructure/session.ts';
import { orvalMutator } from '@/infrastructure/http';

const USER = { id: 'u1', username: 'ada', email: 'ada@example.com', admin: false };

/**
 * Responses per endpoint, rebuilt for each test so one case cannot leak into the next.
 *
 * Keyed by `METHOD /path` and consulted by the mock below. A test that needs a different answer
 * overwrites one entry rather than re-mocking the module, which keeps the default shape — the one
 * every other test relies on — in exactly one place.
 */
let responses: Record<string, unknown>;

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn((config: { url: string; method: string }) => {
        const key = `${config.method?.toUpperCase()} ${config.url}`;
        // Unknown endpoint resolves to `undefined` rather than throwing: several actions ignore
        // their response body entirely, and forcing every one of them into the table above would
        // make the table a list of the endpoints called rather than of the answers that matter.
        return Promise.resolve(responses[key]);
    })
}));

/** Every request URL handed to the transport, in order. */
const requestedUrls = () =>
    vi.mocked(orvalMutator).mock.calls.map((call) => (call[0] as { url: string }).url);

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    responses = {
        'POST /account/login': { token: 'jwt-token' },
        'GET /account': { data: USER },
        'POST /account/reset': { data: undefined },
        'POST /account/reset-confirm': { data: undefined },
        'DELETE /account': { data: undefined },
        'DELETE /account/delete-confirm': { data: undefined },
        'POST /account/logout': { data: undefined },
        'POST /account/logout-all': { data: undefined },
        'PUT /account': { data: { ...USER, username: 'ada2' } }
    };
});

describe('login', () => {
    it('stores the token, then loads the profile with it', () =>
        useAccountStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => {
                // Order is the assertion: a profile fetched before the token is attached is an
                // anonymous request, which answers 401 rather than the account.
                expect(requestedUrls()).toEqual(['/account/login', '/account']);
                expect(useSessionStore().accessToken).toBe('jwt-token');
            }));

    it('publishes the viewer the router guards read', () =>
        useAccountStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => {
                const session = useSessionStore();

                // The projection, not the record: the shell is not allowed to know what a `User`
                // is, so anything beyond these three fields leaking in is a regression.
                expect(session.viewer).toEqual({
                    id: 'u1',
                    email: 'ada@example.com',
                    admin: false
                });
                expect(session.isAuth).toBe(true);
                expect(session.isAdmin).toBe(false);
            }));

    it('marks an admin as one, so the admin routes resolve', () => {
        responses['GET /account'] = { data: { ...USER, admin: true } };

        return useAccountStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => {
                expect(useSessionStore().isAdmin).toBe(true);
            });
    });

    it('leaves the session anonymous when the response carries no token', () => {
        responses['POST /account/login'] = { data: {} };

        return useAccountStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => {
                expect(useSessionStore().accessToken).toBeUndefined();
            });
    });
});

describe('fetchProfile', () => {
    it('selects the identifier the profile updates address', () =>
        useAccountStore()
            .fetchProfile(true)
            .then(() => {
                // `updateProfile` rejects without this, so a fetch that loads the record but does
                // not select it leaves the store readable and unwritable.
                expect(useAccountStore().profile).toMatchObject({ id: 'u1' });
            }));

    it('publishes the viewer without a login having happened', () =>
        // The restore path: a returning visitor holds a refresh cookie, so `tryRestoreAuth` calls
        // this directly and the guards depend on it filling the projection.
        useAccountStore()
            .fetchProfile(true)
            .then(() => {
                expect(useSessionStore().viewer).toMatchObject({ id: 'u1' });
            }));

    it('leaves the viewer alone when the response carries no payload', () => {
        responses['GET /account'] = { data: undefined };

        return useAccountStore()
            .fetchProfile(true)
            .then(() => {
                expect(useSessionStore().viewer).toBeUndefined();
                expect(useSessionStore().isAuth).toBe(false);
            });
    });
});

describe('updateProfile', () => {
    it('rejects when no profile has been loaded', () =>
        // Not a thrown error: the caller is a form submit handler, and an unhandled rejection here
        // would surface as a silent no-op on the button.
        expect(useAccountStore().updateProfile({ username: 'ada2' })).rejects.toThrow(
            'invalid user'
        ));

    it('sends only the fields a user owns, to the self-service endpoint', () => {
        const store = useAccountStore();

        return store
            .fetchProfile(true)
            .then(() => store.updateProfile({ username: 'ada2', admin: true }))
            .then(() => {
                // The write, not the refetch that follows it — `updateProfile` re-reads the
                // record afterwards, so the LAST call is a GET.
                const last = vi
                    .mocked(orvalMutator)
                    .mock.calls.map(
                        (call) =>
                            call[0] as {
                                url: string;
                                method: string;
                                data: Record<string, unknown>;
                            }
                    )
                    .find(({ method }) => method?.toUpperCase() === 'PUT')!;

                // PUT /account, never the admin write: routing self-service through
                // `/users/{id}` is the 403 this store used to ship.
                expect(last.url).toBe('/account');
                // `admin` was passed in and must NOT reach the wire: a user editing their own
                // record cannot promote themselves, and the store is the only thing enforcing it.
                expect(Object.keys(last.data).toSorted()).toEqual(
                    ['email', 'username', 'locale', 'imageUrl'].toSorted()
                );
                expect(last.data.username).toBe('ada2');
            });
    });
});

describe('locale preference', () => {
    it('persists the chosen language through PUT /account', () => {
        const store = useAccountStore();

        return store
            .fetchProfile(true)
            .then(() => store.updateProfile({ locale: 'it' }))
            .then(() => {
                const put = vi
                    .mocked(orvalMutator)
                    .mock.calls.map(
                        (call) =>
                            call[0] as { method?: string; url: string; data?: { locale?: string } }
                    )
                    .find(
                        (call) => call.method?.toUpperCase() === 'PUT' && call.url === '/account'
                    );
                // The record carries the language, so the next login can re-apply it.
                expect(put?.data?.locale).toBe('it');
            });
    });
});

describe('logout', () => {
    it('ends THIS session only and clears the state the guards read', () => {
        const store = useAccountStore();

        return store
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => store.logout())
            .then(() => {
                const session = useSessionStore();

                // The single-session endpoint: other devices stay signed in, which is what a
                // shared-machine logout should mean. `logoutEverywhere` is the wide one.
                expect(requestedUrls().at(-1)).toBe('/account/logout');
                // The whole point of the action: a stale `isAuth` would let the guards wave the
                // next navigation through with no token to back it.
                expect(session.accessToken).toBeUndefined();
                expect(session.viewer).toBeUndefined();
                expect(session.isAuth).toBe(false);
            });
    });

    it('drops the cached profile, so the next visitor is not served this one', () => {
        const store = useAccountStore();

        return store
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => store.logout())
            .then(() => {
                expect(store.profile).toBeUndefined();
            });
    });
});

describe('the password reset flow', () => {
    it('requests a token for an email', () =>
        useAccountStore()
            .requestPasswordReset('ada@example.com')
            .then(() => {
                expect(requestedUrls()).toEqual(['/account/reset']);
            }));

    it('confirms with the token and the new password', () =>
        useAccountStore()
            .confirmPasswordReset('reset-token', 'hunter3hunter3', 'hunter3hunter3')
            .then(() => {
                const last = vi.mocked(orvalMutator).mock.calls.at(-1)![0] as {
                    url: string;
                    data: Record<string, unknown>;
                };

                expect(last.url).toBe('/account/reset-confirm');
                expect(last.data).toMatchObject({ token: 'reset-token' });
            }));
});

describe('the account deletion flow', () => {
    it('requests deletion without touching the session', () => {
        const store = useAccountStore();

        return store
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => store.requestAccountDelete())
            .then(() => {
                // Only a token has been emailed at this point. Signing the visitor out here would
                // strand them holding a confirmation link they can no longer use.
                expect(requestedUrls().at(-1)).toBe('/account');
                expect(useSessionStore().isAuth).toBe(true);
            });
    });

    it('clears the session once deletion is confirmed', () => {
        const store = useAccountStore();

        return store
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => store.confirmAccountDelete('delete-token'))
            .then(() => {
                const session = useSessionStore();

                expect(requestedUrls().at(-1)).toBe('/account/delete-confirm');
                expect(session.accessToken).toBeUndefined();
                expect(session.isAuth).toBe(false);
                expect(store.profile).toBeUndefined();
            });
    });
});

describe('logoutEverywhere', () => {
    it('calls logout-all — the compromised-credentials button', () => {
        const store = useAccountStore();

        return store
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => store.logoutEverywhere())
            .then(() => {
                expect(requestedUrls().at(-1)).toBe('/account/logout-all');
                expect(useSessionStore().isAuth).toBe(false);
            });
    });
});

describe('the self-service actions', () => {
    beforeEach(() => {
        responses['POST /account/password'] = { data: undefined };
        responses['GET /account/sessions'] = {
            data: { sessions: [{ id: 's1', current: true }] }
        };
        responses['DELETE /account/sessions/s1'] = { data: undefined };
        responses['POST /account/verify-request'] = { data: undefined };
        responses['POST /account/verify-confirm'] = { data: undefined };
        responses['GET /account/addresses'] = {
            data: {
                addresses: [
                    {
                        id: 'a1',
                        fullName: 'Ada',
                        street: 'Via Roma 1',
                        city: 'Modena',
                        zip: '41121',
                        country: 'IT',
                        default: true
                    }
                ]
            }
        };
        responses['POST /account/addresses'] = responses['GET /account/addresses'];
        responses['PUT /account/addresses/a1'] = responses['GET /account/addresses'];
        responses['DELETE /account/addresses/a1'] = { data: undefined };
    });

    it('changePassword sends all three fields to its own endpoint', () =>
        useAccountStore()
            .changePassword('old-secret', 'new-secret', 'new-secret')
            .then(() => {
                const last = vi.mocked(orvalMutator).mock.calls.at(-1)![0] as {
                    url: string;
                    data: Record<string, unknown>;
                };
                expect(last.url).toBe('/account/password');
                expect(Object.keys(last.data).toSorted()).toEqual(
                    ['currentPassword', 'password', 'passwordConfirm'].toSorted()
                );
            }));

    it('revokeSession reloads the list it changed', () => {
        const store = useAccountStore();
        return store
            .fetchSessions()
            .then(() => store.revokeSession('s1'))
            .then(() => {
                expect(requestedUrls().slice(-3)).toEqual([
                    '/account/sessions',
                    '/account/sessions/s1',
                    '/account/sessions'
                ]);
                expect(store.sessions.map(({ id }) => id)).toEqual(['s1']);
            });
    });

    it('a sessions payload without the list reads as no sessions', () => {
        responses['GET /account/sessions'] = { data: undefined };
        const store = useAccountStore();
        return store.fetchSessions().then(() => {
            expect(store.sessions).toEqual([]);
        });
    });

    it('confirmEmailVerification refetches the profile only for a live session', () => {
        const store = useAccountStore();
        // Guest first: spend a token with no session — no profile call may follow.
        return store
            .confirmEmailVerification('a-token')
            .then(() => {
                expect(requestedUrls()).toEqual(['/account/verify-confirm']);
            })
            .then(() => store.login('ada@example.com', 'hunter2hunter2'))
            .then(() => store.confirmEmailVerification('a-token'))
            .then(() => {
                // Authenticated: the freshly verified record is pulled back in.
                expect(requestedUrls().at(-1)).toBe('/account');
            });
    });

    it('requestEmailVerification asks for the re-send', () =>
        useAccountStore()
            .requestEmailVerification()
            .then(() => {
                expect(requestedUrls().at(-1)).toBe('/account/verify-request');
            }));

    it('the address book replaces the whole list on every write', () => {
        const store = useAccountStore();
        return store
            .fetchAddresses()
            .then(() =>
                store.addAddress({
                    fullName: 'Ada',
                    street: 'Via Roma 1',
                    city: 'Modena',
                    zip: '41121',
                    country: 'IT'
                })
            )
            .then(() => store.updateAddress('a1', { default: true }))
            .then(() => {
                expect(store.addresses.map(({ id }) => id)).toEqual(['a1']);
            })
            .then(() => store.removeAddress('a1'))
            .then(() => {
                // A payload-less answer is an empty book — the `?? []` arm.
                expect(store.addresses).toEqual([]);
            });
    });
});

src/modules/products/tests/store.spec.ts.source:
/**
 * Unit tests for the products store.
 *
 * The CRUD wrappers are thin over `@guebbit/vue-toolkit`, so testing them would be testing the
 * toolkit. What is *this repo's* logic is the multipart branch: whether a call goes out as JSON
 * or as `FormData`, and how that `FormData` is built.
 *
 * `@api` is deliberately NOT mocked. The FormData encoding lives in the generated client
 * (orval's `splitByContentType` output), so mocking `@api` would assert only that the store
 * picked a function name and would stop covering the encoding itself. Mocking the transport
 * instead runs store → generated client → `orvalMutator` for real, and asserts the request that
 * actually goes on the wire: repeated `categories` rather than `categories[0]`, and unset
 * optional fields omitted rather than sent as the string `"undefined"`. Both are invisible to
 * TypeScript, and a regression in either sends a request the backend silently misreads.
 *
 * Each `it` RETURNS its chain rather than awaiting — vitest fails a test whose returned promise
 * rejects, so the assertions inside a `.then` are as binding as awaited ones.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useProductsStore } from '@/modules/products/store';
import { orvalMutator } from '@/infrastructure/http';
import type { Product } from '@types';

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn(() => Promise.resolve({ data: { id: 'p1', title: 'T', price: 1 } }))
}));

/** The axios config handed to orvalMutator on its most recent call. */
const lastRequest = () => {
    const call = vi.mocked(orvalMutator).mock.calls.at(-1);
    if (!call) throw new Error('orvalMutator was never called');
    return call[0] as { url: string; method: string; data: unknown };
};

/** As above, asserting the body was multipart-encoded. */
const lastFormData = () => {
    const { data } = lastRequest();
    if (!(data instanceof FormData)) throw new Error('last request body was not FormData');
    return data;
};

const PRODUCT: Product = {
    id: 'p1',
    title: 'Gadget',
    price: 49.99,
    description: 'A gadget',
    imageUrl: 'https://example.com/g.jpg',
    categories: ['tools'],
    tags: ['new'],
    active: true
} as Product;

/** Makes the transport answer with a paginated envelope for this test. */
const respondWithItems = (items: unknown[]) =>
    vi.mocked(orvalMutator).mockResolvedValue({ data: { items } } as never);

/** The query parameters of the most recent request. */
const lastParameters = () =>
    (lastRequest() as unknown as { params: Record<string, unknown> }).params;

describe('useProductsStore', () => {
    beforeEach(() => {
        setActivePinia(createPinia());
        vi.clearAllMocks();
    });

    describe('createProduct', () => {
        it('posts JSON when no image is attached', () =>
            useProductsStore()
                .createProduct({ title: 'Gadget', price: 49.99 })
                .then(() => {
                    const request = lastRequest();
                    expect(request).toMatchObject({ url: '/products', method: 'POST' });
                    expect(request.data).not.toBeInstanceOf(FormData);
                    expect(request.data).toMatchObject({ title: 'Gadget', price: 49.99 });
                }));

        it('resolves with the created product, not with the envelope', () =>
            useProductsStore()
                .createProduct({ title: 'Gadget', price: 49.99 })
                .then((created) => {
                    // `ProductCreate.vue` routes to `/products/${created.id}` on success, so a
                    // wrapper that forgot to unwrap `response.data` would navigate to
                    // `/products/undefined` rather than fail visibly here.
                    expect(created).toEqual({ id: 'p1', title: 'T', price: 1 });
                }));

        it('posts multipart to /products when an image is attached', () =>
            useProductsStore()
                .createProduct({ title: 'Gadget', price: 49.99, imageUpload: new Blob(['x']) })
                .then(() => {
                    expect(lastRequest()).toMatchObject({ url: '/products', method: 'POST' });
                    expect(lastFormData().get('title')).toBe('Gadget');
                }));

        it('sends a Blob image, not only a File', () =>
            // The contract types the field as Blob, and encoders that recurse into anything that
            // is not a File (axios' `toFormData` among them) drop a plain Blob silently.
            useProductsStore()
                .createProduct({ title: 'Gadget', price: 49.99, imageUpload: new Blob(['x']) })
                .then(() => {
                    expect(lastFormData().get('imageUpload')).toBeInstanceOf(Blob);
                }));

        it('sends categories and tags as repeated fields, not indexed keys', () =>
            useProductsStore()
                .createProduct({
                    title: 'Gadget',
                    price: 49.99,
                    categories: ['tools', 'home'],
                    tags: ['new'],
                    imageUpload: new Blob(['x'])
                })
                .then(() => {
                    const formData = lastFormData();
                    expect(formData.getAll('categories')).toEqual(['tools', 'home']);
                    expect(formData.getAll('tags')).toEqual(['new']);
                    expect([...formData.keys()]).not.toContain('categories[0]');
                }));

        it('omits unset optional fields instead of sending the string "undefined"', () =>
            useProductsStore()
                .createProduct({
                    title: 'Gadget',
                    price: 49.99,
                    description: undefined,
                    imageUpload: new Blob(['x'])
                })
                .then(() => {
                    const formData = lastFormData();
                    expect(formData.has('description')).toBe(false);
                    expect([...formData.values()]).not.toContain('undefined');
                }));

        /**
         * `ProductCreate.vue` passes `onUploadProgress` through the second argument to drive its
         * progress bar. `createProduct` had no `options` parameter until that view existed.
         */
        it('forwards the upload progress callback to the transport', () => {
            const onUploadProgress = vi.fn();

            return useProductsStore()
                .createProduct(
                    { title: 'Gadget', price: 49.99, imageUpload: new Blob(['x']) },
                    { onUploadProgress }
                )
                .then(() => {
                    expect(orvalMutator).toHaveBeenCalledWith(
                        expect.anything(),
                        expect.objectContaining({ onUploadProgress })
                    );
                });
        });
    });

    describe('updateProduct', () => {
        it('puts JSON when no new image is attached', () =>
            useProductsStore()
                .updateProduct('p1', { title: 'Renamed', price: 9.99 })
                .then(() => {
                    const request = lastRequest();
                    expect(request).toMatchObject({ url: '/products/p1', method: 'PUT' });
                    expect(request.data).not.toBeInstanceOf(FormData);
                    expect(request.data).toMatchObject({ title: 'Renamed' });
                }));

        it('puts multipart when an image is attached', () =>
            useProductsStore()
                .updateProduct('p1', {
                    title: 'Renamed',
                    price: 9.99,
                    imageUpload: new Blob(['x'])
                })
                .then(() => {
                    expect(lastRequest()).toMatchObject({ url: '/products/p1', method: 'PUT' });
                    expect(lastFormData().get('title')).toBe('Renamed');
                }));

        /**
         * The other half of `optimisticPatch`, and the half the Blob test cannot see: an
         * implementation that patched NOTHING would also leave no `imageUpload` behind. What
         * makes the patch worth having is that the edited row shows the new title while the
         * request is still in flight.
         */
        it('shows the edited fields before the response arrives', () => {
            const store = useProductsStore();
            store.addProduct(PRODUCT);

            // `Once`, deliberately: the suite's `beforeEach` calls `vi.clearAllMocks()`, which
            // clears recorded calls but NOT an implementation set with `mockReturnValue`. A
            // persistent override here would hand every later test this same settled promise.
            let release!: (value: unknown) => void;
            const transportResponse = new Promise((resolve) => {
                release = resolve;
            });
            vi.mocked(orvalMutator).mockImplementationOnce(() => transportResponse as never);

            const pending = store.updateProduct('p1', {
                title: 'Renamed',
                price: 9.99,
                imageUpload: new Blob(['x'])
            });

            // `waitFor` rather than a counted number of microtasks: the toolkit awaits
            // `cancelQueries()` before writing the optimistic record, so how many ticks that
            // takes is TanStack's business and not something this test should encode. The
            // request is still unresolved throughout — `release` has not been called yet — so
            // this can only pass if the store was patched ahead of the response.
            return vi
                .waitFor(() => {
                    expect(store.products.p1.title).toBe('Renamed');
                })
                .then(() => {
                    expect(store.products.p1).not.toHaveProperty('imageUpload');
                    release({ data: { ...PRODUCT, title: 'Renamed' } });
                    return pending;
                })
                .then(() => {
                    expect(store.products.p1.title).toBe('Renamed');
                });
        });

        it('never parks the uploaded Blob in store state', () => {
            const store = useProductsStore();
            store.addProduct(PRODUCT);

            return store
                .updateProduct('p1', {
                    title: 'Renamed',
                    price: 9.99,
                    imageUpload: new Blob(['x'])
                })
                .then(() => {
                    expect(store.products.p1).not.toHaveProperty('imageUpload');
                });
        });

        /**
         * The reason `orvalMutator` takes a second argument at all — `ProductEdit.vue` passes
         * `onUploadProgress` through it to drive its progress bar.
         */
        it('forwards the upload progress callback to the transport', () => {
            const onUploadProgress = vi.fn();

            return useProductsStore()
                .updateProduct(
                    'p1',
                    { title: 'Renamed', price: 9.99, imageUpload: new Blob(['x']) },
                    { onUploadProgress }
                )
                .then(() => {
                    expect(orvalMutator).toHaveBeenCalledWith(
                        expect.anything(),
                        expect.objectContaining({ onUploadProgress })
                    );
                });
        });
    });

    describe('deleteProduct', () => {
        it('calls the delete endpoint with the product id', () =>
            useProductsStore()
                .deleteProduct('p1')
                .then(() => {
                    expect(lastRequest()).toMatchObject({
                        url: '/products/p1',
                        method: 'DELETE'
                    });
                }));
    });

    describe('hardDeleteProduct', () => {
        /*
         * A separate method rather than a flag on `deleteProduct`, because the two are not the same
         * operation: the soft form sets `deletedAt` and an admin can toggle it back, this one is
         * irreversible. Distinct names mean the destructive path cannot be reached by passing the
         * wrong boolean — so what is worth pinning is that it hits the `/hard` URL and nothing else.
         */
        it('calls the /hard endpoint with the product id', () =>
            useProductsStore()
                .hardDeleteProduct('p1')
                .then(() => {
                    expect(lastRequest()).toMatchObject({
                        url: '/products/p1/hard',
                        method: 'DELETE'
                    });
                }));

        it('is a different URL from the soft delete', () =>
            useProductsStore()
                .deleteProduct('p1')
                .then(() => {
                    const soft = lastRequest()?.url;
                    return useProductsStore()
                        .hardDeleteProduct('p1')
                        .then(() => {
                            expect(lastRequest()?.url).not.toBe(soft);
                        });
                }));
    });

    /**
     * Read paths.
     *
     * The pagination/caching machinery belongs to the toolkit and is not re-tested here. What IS
     * this repo's logic is the request each wrapper builds and the envelope depth it unwraps:
     * list endpoints answer `{ data: { items } }` while single-record ones answer `{ data }`, and
     * `watchSearchProducts` sends `filters.id` as the `id` query parameter.
     *
     * That last one is worth pinning: `id` is the name the API reads, on both the GET query and
     * the `POST /products/search` body, and getting it wrong is invisible to TypeScript — every
     * candidate name is `string | undefined` — so it shows up only as a filter that appears to
     * work and returns the unfiltered catalogue.
     */
    describe('read paths', () => {
        describe('fetchProducts', () => {
            it('requests the collection and unwraps the paginated envelope', () => {
                respondWithItems([PRODUCT]);

                return useProductsStore()
                    .fetchProducts()
                    .then((result) => {
                        expect(lastRequest()).toMatchObject({ url: '/products', method: 'GET' });
                        // `.data.items`, not `.data` — one level too shallow yields the envelope
                        // itself, which renders as an empty list rather than as an error.
                        expect(result).toEqual([PRODUCT]);
                    });
            });
        });

        describe('fetchPaginationProducts', () => {
            it('defaults to the first page of ten', () => {
                respondWithItems([]);

                return useProductsStore()
                    .fetchPaginationProducts()
                    .then(() => {
                        expect(lastRequest()).toMatchObject({
                            url: '/products',
                            method: 'GET',
                            params: { page: 1, pageSize: 10 }
                        });
                    });
            });

            it('passes an explicit page and size through', () => {
                respondWithItems([]);

                return useProductsStore()
                    .fetchPaginationProducts(3, 25)
                    .then(() => {
                        expect(lastRequest()).toMatchObject({
                            params: { page: 3, pageSize: 25 }
                        });
                    });
            });
        });

        describe('fetchProduct', () => {
            it('requests one product and unwraps a single-record envelope', () => {
                vi.mocked(orvalMutator).mockResolvedValue({ data: PRODUCT } as never);

                return useProductsStore()
                    .fetchProduct('p1')
                    .then((result) => {
                        expect(lastRequest()).toMatchObject({
                            url: '/products/p1',
                            method: 'GET'
                        });
                        // One level shallower than the list case, deliberately.
                        expect(result).toEqual(PRODUCT);
                    });
            });
        });

        describe('watchSearchProducts', () => {
            it('sends the store filters as query parameters, id included', () => {
                respondWithItems([]);
                const store = useProductsStore();
                store.filters = { text: 'gad', id: 'p1', minPrice: 5, maxPrice: 50 };

                return store
                    .watchSearchProducts()
                    .search()
                    .then(() => {
                        const parameters = lastParameters();
                        expect(parameters).toMatchObject({
                            text: 'gad',
                            // `id`, the name the API actually reads; `productId` filters nothing.
                            id: 'p1',
                            minPrice: 5,
                            maxPrice: 50
                        });
                        expect(parameters.productId).toBeUndefined();
                    });
            });

            it('reports a failed search to the supplied error handler', () => {
                const failure = new Error('network down');
                vi.mocked(orvalMutator).mockRejectedValue(failure);
                const onError = vi.fn();

                return useProductsStore()
                    .watchSearchProducts({ onError })
                    .search()
                    .catch(() => {})
                    .then(() => {
                        // The list view has no other way to learn the search failed — without
                        // this the page simply stops updating with no message.
                        expect(onError).toHaveBeenCalledWith(failure, expect.anything());
                    });
            });
        });

        describe('fetchFacets', () => {
            const FACETS = {
                categories: [{ name: 'tools', count: 3 }],
                tags: [{ name: 'new', count: 1 }]
            };

            it('parks the facets on the store and resolves with them', () => {
                vi.mocked(orvalMutator).mockResolvedValue({ data: FACETS } as never);
                const store = useProductsStore();

                return store.fetchFacets().then((result) => {
                    expect(lastRequest()).toMatchObject({
                        url: '/products/categories',
                        method: 'GET'
                    });
                    // Both halves matter: the view reads `store.facets` to render the chips, and
                    // the caller reads the return value. An implementation that only did one of
                    // the two would leave either the chips empty or the caller with `undefined`.
                    expect(store.facets).toEqual(FACETS);
                    expect(result).toEqual(FACETS);
                });
            });
        });
    });

    /*
     * There is deliberately NO test for the five-minute `TTL`.
     *
     * It is one number handed to `useStructureCrudApi`, and the only way to observe it is to drive
     * the toolkit's cache: fetch twice and count requests, or move the clock and count again. Both
     * assert that TanStack Query's `staleTime` works, which is TanStack's suite's job and not this
     * one's — the same rule stated at the top of this file for the CRUD wrappers.
     *
     * The consequence is on the record rather than worked around: Stryker's mutants on that
     * expression (`5 * 60 / 1000`, `5 / 60`) and on the options object around it survive, and they
     * should. A mutant in a value passed straight to a dependency is not this repo's to kill, and
     * writing a toolkit test to move a score is how the score stops meaning anything.
     */

    /**
     * Pinia identifies a store by the string passed to `defineStore`, and that string is also the
     * key devtools and any persistence plugin use. Nothing else in the suite would notice it
     * changing, because every test reaches the store through `useProductsStore()`.
     */
    it('is registered under the "products" id', () => {
        expect(useProductsStore().$id).toBe('products');
    });
});

tests/unit/infrastructure/formatters.pro.source:
/**
 * Property-based tests — `src/infrastructure/formatters.ts` and `src/infrastructure/uploads.ts`.
 *
 * The example-based suites next door assert what these functions do for the inputs someone
 * thought of. These assert what must hold for EVERY input, which is a different question and
 * catches a different class of bug: the boundary nobody enumerated, the surrogate pair, the
 * `-0`, the string that is whitespace in a script you have never seen.
 *
 * Why this layer exists at all: it is the general form of a fix this repo already paid for the
 * expensive way. `responseSchemaMap.ts` was tested by sampling a handful of rows from a 52-row
 * table and scored 55% mutation with 182 survivors in that one file; replacing the sample with
 * exhaustive generation took it to ~96% and the whole suite from 55% to 81%. Sampling a space
 * you could have covered is the failure mode, and generation is the answer to it.
 *
 * TWO RULES, both non-negotiable and both about determinism:
 *
 *   1. **Every run is seeded.** `fast-check` defaults to a random seed, which makes a failure
 *      un-reproducible and — worse — makes a test that fails one run in fifty look like flake.
 *      A fixed seed means this suite either passes or fails, the same way every other test does.
 *   2. **Every counterexample becomes a regression case**, written out as an ordinary `it()` with
 *      the seed that found it in a comment. The property stays as the general statement; the
 *      example stays as the thing that once broke.
 *
 * `numRuns` is deliberately modest. These run on the pre-commit path, where the frontend gate is
 * already ~8.5 minutes; a property that needs ten thousand cases to find its bug is a property
 * that wants a nightly, not a commit hook.
 *
 * ── SPLIT WITH `formatters.spec.ts` / `uploads.spec.ts` ─────────────────────────────────────
 * Those files are example-based and own the SPECIFIC values: the exact size boundary, the
 * non-canonical `image/jpg`, the shipped copy of a message. This file owns what only generation
 * can claim — that a rule holds for EVERY input, not for the ones someone thought of.
 *
 * Check there before adding a case here. A fact asserted twice is maintained twice.
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';
import fc from 'fast-check';
import {
    EMPTY_VALUE,
    formatCurrency,
    formatFlag,
    formatText,
    formatDateTime,
    formatDate
} from '@/infrastructure/formatters';
import {
    ACCEPTED_IMAGE_TYPES,
    MAX_UPLOAD_BYTES,
    formatUploadSize,
    isAcceptedImageType,
    isWithinUploadSizeLimit
} from '@/infrastructure/uploads';

/**
 * One seed for the whole file, and one place to change it.
 *
 * `endOnFailure` trims the shrunk counterexample instead of continuing to shrink for a while
 * after it has one, which keeps a failure message short enough to paste into a regression case.
 */
const RUN = { seed: 20_260_808, numRuns: 200, endOnFailure: true } as const;

/**
 * The two nullish spellings these signatures actually accept.
 *
 * `formatText(value?: string | null)`, `formatCurrency(value?: number | null)` and
 * `formatFlag(value: boolean | null | undefined, …)` all admit both, and the properties below
 * depend on both taking the fallback branch — so neither can be dropped to satisfy a lint rule
 * that would rather this codebase had only `undefined`.
 */
const nullish = () => fc.constantFrom(null, undefined);

/** The locale the formatters read. Pinned so a machine's locale cannot decide the assertions. */
vi.mock('@/infrastructure/i18n.ts', () => ({
    getCurrentLocale: () => 'en'
}));

beforeEach(() => {
    vi.clearAllMocks();
});

describe('formatText', () => {
    it('never returns an empty or blank string, for any input', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                const result = formatText(value);
                // The whole purpose of the function: a table cell always has something in it.
                expect(result.trim().length).toBeGreaterThan(0);
            }),
            RUN
        ));

    it('returns the fallback for exactly the inputs that carry no text', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                // A biconditional, not two separate cases: this is the whole decision rule, and
                // asserting it both ways is what stops the boundary drifting in one direction.
                const isBlank = value === undefined || value.trim().length === 0;
                expect(formatText(value) === EMPTY_VALUE).toBe(isBlank || value === EMPTY_VALUE);
            }),
            RUN
        ));

    it('returns non-blank input UNCHANGED, rather than trimmed', () =>
        fc.assert(
            fc.property(fc.string({ minLength: 1 }), (value) => {
                fc.pre(value.trim().length > 0);
                // The emptiness test trims; the return value does not. A refactor that returned
                // `value.trim()` would pass every "is it non-empty" assertion above.
                expect(formatText(` ${value} `)).toBe(` ${value} `);
            }),
            RUN
        ));

    it('is idempotent', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                expect(formatText(formatText(value))).toBe(formatText(value));
            }),
            RUN
        ));
});

describe('formatCurrency', () => {
    it('returns the fallback for every non-number, and never for a number', () =>
        fc.assert(
            fc.property(
                fc.oneof(
                    fc.double({ noNaN: true, noDefaultInfinity: true }),
                    nullish(),
                    fc.string(),
                    fc.boolean()
                ),
                (value) => {
                    const result = formatCurrency(value as number | null | undefined);
                    expect(result === EMPTY_VALUE).toBe(typeof value !== 'number');
                }
            ),
            RUN
        ));

    it('never throws, for any amount and any currency code', () =>
        fc.assert(
            fc.property(
                fc.double({ noNaN: true, noDefaultInfinity: true }),
                fc.string(),
                (value, currency) => {
                    // The `catch` in formatCurrency exists for exactly this: an unknown or
                    // malformed ISO 4217 code makes Intl throw a RangeError, and a product page
                    // must not 500 over a currency string. Generation is what reaches the codes
                    // nobody would think to write down.
                    expect(() => formatCurrency(value, currency)).not.toThrow();
                }
            ),
            RUN
        ));

    it('degrades to a plain number rather than the fallback on a bad currency', () =>
        fc.assert(
            fc.property(fc.double({ noNaN: true, noDefaultInfinity: true }), (value) => {
                // The failure path must still show the AMOUNT. Returning EMPTY_VALUE here would
                // hide a real price behind an em dash because of a config typo.
                expect(formatCurrency(value, 'not-a-currency')).not.toBe(EMPTY_VALUE);
            }),
            RUN
        ));

    it('renders every finite amount with at least one digit', () =>
        fc.assert(
            fc.property(fc.double({ noNaN: true, noDefaultInfinity: true }), (value) => {
                expect(formatCurrency(value)).toMatch(/\d/);
            }),
            RUN
        ));
});

describe('formatFlag', () => {
    it('returns one of exactly three things, and the fallback only for nullish', () =>
        fc.assert(
            fc.property(
                fc.option(fc.boolean(), { nil: undefined }),
                fc.string(),
                fc.string(),
                (value, trueLabel, falseLabel) => {
                    // The expected value is computed first and asserted once, rather than
                    // branching around two `expect`s — same property, but it states the whole
                    // decision rule as one expression.
                    //
                    // `false` is the classic place this breaks: a `!value` guard would send it
                    // down the fallback branch alongside null and undefined.
                    const expected =
                        value === undefined ? EMPTY_VALUE : value ? trueLabel : falseLabel;

                    expect(formatFlag(value, trueLabel, falseLabel)).toBe(expected);
                }
            ),
            RUN
        ));
});

describe('formatDateTime', () => {
    it('never throws, whatever string it is handed', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                // The value comes off the wire. An unparseable one yields "Invalid Date", which
                // is ugly but must not be an exception in a render.
                expect(() => formatDateTime(value)).not.toThrow();
            }),
            RUN
        ));

    it('returns the fallback for every falsy input', () =>
        fc.assert(
            fc.property(fc.oneof(nullish(), fc.constant('')), (value) => {
                expect(formatDateTime(value)).toBe(EMPTY_VALUE);
            }),
            RUN
        ));
});

describe('formatDate', () => {
    it('never throws, whatever string it is handed', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                // Same contract as `formatDateTime`: off-the-wire input, never an exception mid-render.
                expect(() => formatDate(value)).not.toThrow();
            }),
            RUN
        ));

    it('returns the fallback for every falsy input', () =>
        fc.assert(
            fc.property(fc.oneof(nullish(), fc.constant('')), (value) => {
                expect(formatDate(value)).toBe(EMPTY_VALUE);
            }),
            RUN
        ));

    it('is never longer than the datetime it drops the time from', () =>
        fc.assert(
            fc.property(fc.date({ noInvalidDate: true }), (date) => {
                const iso = date.toISOString();
                expect(formatDate(iso).length).toBeLessThanOrEqual(formatDateTime(iso).length);
            }),
            RUN
        ));
});

/** A File whose `type` and `size` are the only fields the upload predicates read. */
const makeFile = (type: string, size: number) => ({ type, size }) as File;

describe('upload predicates', () => {
    it('accepts a type if and only if it is on the shared list', () =>
        fc.assert(
            fc.property(fc.string(), fc.nat(), (type, size) => {
                expect(isAcceptedImageType(makeFile(type, size))).toBe(
                    (ACCEPTED_IMAGE_TYPES as readonly string[]).includes(type)
                );
            }),
            RUN
        ));

    it('is case-sensitive about the mime type, matching the backend', () =>
        fc.assert(
            fc.property(fc.constantFrom(...ACCEPTED_IMAGE_TYPES), (type) => {
                // Documented rather than assumed: the backend's fileFilter compares verbatim, so
                // a client-side check that lowercased first would accept files the server then
                // rejects — a worse experience than rejecting early.
                expect(isAcceptedImageType(makeFile(type.toUpperCase(), 1))).toBe(false);
            }),
            RUN
        ));

    it('treats the size limit as inclusive, on both sides of the boundary', () =>
        fc.assert(
            fc.property(fc.nat(), (size) => {
                expect(isWithinUploadSizeLimit(makeFile('image/png', size))).toBe(
                    size <= MAX_UPLOAD_BYTES
                );
            }),
            RUN
        ));

    /*
     * The exact boundary — `MAX_UPLOAD_BYTES` and one byte over — is NOT asserted here. It is
     * already an example in `uploads.spec.ts` ("accepts a file of exactly the limit and rejects
     * one byte more"), and restating it was a straight duplicate. The property above covers the
     * whole range; that one pins the single value `fc.nat()` would only reach by luck.
     */

    it('renders every size as a positive-looking MB label', () =>
        fc.assert(
            fc.property(fc.nat(), (bytes) => {
                const label = formatUploadSize(bytes);
                expect(label).toMatch(/^\d+(\.\d)? MB$/);
                // `Number(...toFixed(1))` drops a trailing ".0", which is the whole reason the
                // conversion is written that way — "5 MB", not "5.0 MB".
                expect(label).not.toMatch(/\.0 MB$/);
            }),
            RUN
        ));

    it('is monotonic in bytes', () =>
        fc.assert(
            fc.property(fc.nat(), fc.nat(), (a, b) => {
                fc.pre(a < b);
                const sizeA = Number.parseFloat(formatUploadSize(a));
                const sizeB = Number.parseFloat(formatUploadSize(b));
                // Rounding may make them equal; it must never invert them.
                expect(sizeA).toBeLessThanOrEqual(sizeB);
            }),
            RUN
        ));
});

