/**
 * Locale router guard — `src/app/middlewares/localeChoice.ts`.
 *
 * This guard runs on every navigation and decides one of three things: proceed as-is, load a
 * language first, or redirect to inject a default locale. Getting the third case wrong is the
 * dangerous one — a guard that returns a redirect when it should return `true` produces an
 * infinite navigation loop, which is why the "already loaded" and "supported" branches are each
 * asserted to return the literal `true` rather than merely something truthy.
 *
 * `fetchLanguageApi` is the simulated server call underneath it. Its documented contract is that
 * it **always resolves, never rejects** — callers deliberately have no `.catch()` — so every
 * failure mode below asserts a resolved empty dictionary rather than a rejection.
 *
 * The i18n module is mocked so `supportedLanguages` / `loadedLanguages` are controlled by the
 * test rather than by whatever `VITE_APP_SUPPORTED_LOCALES` happens to hold in the developer's
 * `.env` — the suite must not change meaning when that file does.
 */

import { beforeEach, afterEach, describe, expect, it, vi } from 'vitest';
import type { RouteLocationNormalized } from 'vue-router';

/** Mutable so individual tests can decide what is supported / already loaded. */
const i18nState = {
    supportedLanguages: ['en', 'it', 'es'],
    loadedLanguages: [] as string[],
    currentLocale: 'en',
    defaultLocale: 'en'
};

// Parameters are declared even though the bodies ignore them: `vi.fn(() => ...)` infers a
// zero-arity signature, so the call sites below (and `toHaveBeenCalledWith`) would not type-check.
const changeLanguageMock = vi.fn((_locale: string) => Promise.resolve());
const updateLocaleMock = vi.fn((_locale: string, _messages: unknown) => Promise.resolve());

vi.mock('@/infrastructure/i18n.ts', () => ({
    get supportedLanguages() {
        return i18nState.supportedLanguages;
    },
    get loadedLanguages() {
        return i18nState.loadedLanguages;
    },
    getCurrentLocale: () => i18nState.currentLocale,
    getDefaultLocale: () => i18nState.defaultLocale,
    changeLanguage: (locale: string) => changeLanguageMock(locale),
    updateLocale: (locale: string, messages: unknown) => updateLocaleMock(locale, messages),
    API_NAMESPACE: 'api'
}));

/**
 * The API's dictionary endpoints. Mocked at the network boundary rather than by stubbing
 * `withApiDictionary`, so the merge itself — this app's keys at the root, the API's under
 * `api.*` — is exercised by the assertions below instead of being replaced by them.
 */
const getLocalesMock = vi.fn(() => Promise.resolve({ data: { locales: ['en', 'it', 'es'] } }));
const getLocaleDictionaryMock = vi.fn(
    (_locale: string): Promise<{ data?: { messages?: Record<string, unknown> } }> =>
        Promise.resolve({ data: { messages: { greeting: 'from-the-api' } } })
);

vi.mock('@api', () => ({
    getLocales: () => getLocalesMock(),
    getLocaleDictionary: (locale: string) => getLocaleDictionaryMock(locale)
}));

const { fetchLanguageApi, localeChoice } = await import('@/app/middlewares/localeChoice');

/** Minimal route stub — the guard only reads name, params and query. */
const routeTo = (overrides: Partial<RouteLocationNormalized> = {}) =>
    ({
        name: 'home',
        params: {},
        query: {},
        ...overrides
    }) as unknown as RouteLocationNormalized;

beforeEach(() => {
    vi.clearAllMocks();
    localStorage.clear();
    i18nState.supportedLanguages = ['en', 'it', 'es'];
    i18nState.loadedLanguages = [];
    i18nState.currentLocale = 'en';
    i18nState.defaultLocale = 'en';
});

afterEach(() => {
    vi.useRealTimers();
});

describe('fetchLanguageApi', () => {
    it('resolves an empty dictionary for an unsupported locale, without waiting', () => {
        vi.useFakeTimers();

        // No timer is scheduled at all on this path, so the promise settles without any
        // advancement — asserted by resolving it before touching the clock.
        return fetchLanguageApi('kl').then((result) => {
            expect(result).toEqual(['kl', {}]);
            // Supported by neither side, so nothing is imported AND nothing is fetched.
            expect(getLocaleDictionaryMock).not.toHaveBeenCalled();
        });
    });

    it('loads a supported locale and returns its dictionary', () => {
        vi.useFakeTimers();
        const promise = fetchLanguageApi('en');
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return promise;
            })
            .then(([locale, dictionary]) => {
                expect(locale).toBe('en');
                // Real file, real import: asserting it is a non-empty object proves the dynamic import
                // actually resolved rather than falling into the catch branch.
                expect(Object.keys(dictionary).length).toBeGreaterThan(0);
            });
    });

    it('delays the first download of a locale by the simulated latency', () => {
        vi.useFakeTimers();
        const setTimeoutSpy = vi.spyOn(globalThis, 'setTimeout');

        void fetchLanguageApi('it');

        // Asserted on the scheduled delay rather than on when the promise settles: the dynamic
        // `import()` underneath resolves over an indeterminate number of microtasks, so a
        // settle-order assertion would be timing-dependent rather than behavioural.
        expect(setTimeoutSpy).toHaveBeenCalledWith(expect.any(Function), 1000);
    });

    it('skips the delay for a locale already downloaded in a previous session', () => {
        localStorage.setItem('downloaded-locales', JSON.stringify(['it']));
        vi.useFakeTimers();
        const setTimeoutSpy = vi.spyOn(globalThis, 'setTimeout');

        void fetchLanguageApi('it');

        // The whole point of persisting the list: latency is simulated once per browser, not
        // once per navigation.
        expect(setTimeoutSpy).toHaveBeenCalledWith(expect.any(Function), 0);
    });

    it('records a locale as downloaded once it has been fetched', () => {
        vi.useFakeTimers();
        const promise = fetchLanguageApi('it');
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return promise;
            })
            .then(() => {
                expect(JSON.parse(localStorage.getItem('downloaded-locales') ?? '[]')).toContain(
                    'it'
                );
            });
    });

    it('deduplicates the stored locale list', () => {
        localStorage.setItem('downloaded-locales', JSON.stringify(['en']));
        vi.useFakeTimers();
        const promise = fetchLanguageApi('en');
        return vi
            .advanceTimersByTimeAsync(0)
            .then(() => {
                return promise;
            })
            .then(() => {
                // Unbounded growth here would be a slow localStorage leak on a long-lived browser.
                expect(JSON.parse(localStorage.getItem('downloaded-locales') ?? '[]')).toEqual([
                    'en'
                ]);
            });
    });

    /**
     * The degradation design C is built around. `es` is supported and has no
     * `src/locales/es.json`, so the UI import rejects — and that must resolve to an empty UI
     * dictionary rather than reject, since callers have no `.catch`. The API's own copy is
     * fetched regardless, so the result is Spanish API messages inside a UI that falls back per
     * key: degrading key by key rather than all-or-nothing.
     */
    it('resolves API copy with an empty UI dictionary when the locale file does not exist', () => {
        vi.useFakeTimers();
        const promise = fetchLanguageApi('es');
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return expect(promise).resolves.toEqual([
                    'es',
                    { api: { greeting: 'from-the-api' } }
                ]);
            })
            .then(() => {
                expect(getLocaleDictionaryMock).toHaveBeenCalledWith('es');
            });
    });

    it('never rejects when the API dictionary cannot be fetched', () => {
        getLocaleDictionaryMock.mockRejectedValueOnce(new Error('network down'));
        vi.useFakeTimers();
        const promise = fetchLanguageApi('it');
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return promise;
            })
            .then(([locale, dictionary]) => {
                // The UI half still loaded; only `api.*` is empty. A dead API must never strand a
                // navigation or blank the interface.
                expect(locale).toBe('it');
                expect(dictionary.api).toEqual({});
                expect(Object.keys(dictionary).length).toBeGreaterThan(1);
            });
    });

    it('puts the API dictionary under api.* and never at the root', () => {
        // `navigation` is deliberately a namespace the SHARED dictionary owns. The module
        // dictionaries are not loaded here, so colliding on a module-owned namespace would prove
        // nothing — the root key would be absent whether or not the reserved namespace worked.
        getLocaleDictionaryMock.mockResolvedValueOnce({
            data: { messages: { navigation: { ['error-already-logged']: 'API COPY' } } }
        });
        vi.useFakeTimers();
        const promise = fetchLanguageApi('it');
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return promise;
            })
            .then(([, dictionary]) => {
                // The API's `navigation` key is namespaced, so it cannot shadow this app's own —
                // which is the collision the reserved namespace exists to prevent.
                expect(dictionary.api).toEqual({
                    navigation: { ['error-already-logged']: 'API COPY' }
                });
                expect(
                    (dictionary.navigation as Record<string, string>)['error-already-logged']
                ).not.toBe('API COPY');
            });
    });

    it('treats a corrupted downloaded-locales entry as empty rather than throwing', () => {
        localStorage.setItem('downloaded-locales', 'not-json{');
        vi.useFakeTimers();

        const promise = fetchLanguageApi('en');
        // Corrupted store ⇒ "not downloaded" ⇒ the full delay applies.
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => promise)
            .then(([locale, dictionary]) => {
                // The locale still loads for real...
                expect(locale).toBe('en');
                expect(Object.keys(dictionary).length).toBeGreaterThan(0);
                // ...and the corrupted value is replaced by a well-formed list, so the browser
                // self-heals instead of re-paying the latency on every navigation forever.
                expect(JSON.parse(localStorage.getItem('downloaded-locales') ?? 'null')).toEqual([
                    'en'
                ]);
            });
    });

    it('still resolves when localStorage writes are unavailable', () => {
        // Private-mode / quota: the documented behaviour is to swallow and simply re-simulate
        // the latency next time, never to fail the navigation.
        const setItemSpy = vi.spyOn(Storage.prototype, 'setItem').mockImplementation(() => {
            throw new Error('QuotaExceededError');
        });
        vi.useFakeTimers();
        const promise = fetchLanguageApi('en');
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return promise;
            })
            .then(([, dictionary]) => {
                expect(Object.keys(dictionary).length).toBeGreaterThan(0);
                setItemSpy.mockRestore();
            });
    });
});

describe('localeChoice', () => {
    it('proceeds without reloading when the locale is already loaded and active', () => {
        i18nState.loadedLanguages = ['en'];
        i18nState.currentLocale = 'en';
        return localeChoice(routeTo({ params: { locale: 'en' } })).then((result) => {
            // Literal `true`, not merely truthy: a redirect object is also truthy, and returning one
            // here is what produces an infinite navigation loop.
            expect(result).toBe(true);
            expect(changeLanguageMock).not.toHaveBeenCalled();
        });
    });

    it('switches the active language when the loaded locale differs from the current one', () => {
        i18nState.loadedLanguages = ['en', 'it'];
        i18nState.currentLocale = 'en';
        return localeChoice(routeTo({ params: { locale: 'it' } })).then((result) => {
            expect(result).toBe(true);
            expect(changeLanguageMock).toHaveBeenCalledWith('it');
            // Already loaded ⇒ no re-download.
            expect(updateLocaleMock).not.toHaveBeenCalled();
        });
    });

    it('fetches, registers and activates a supported but unloaded locale', () => {
        i18nState.loadedLanguages = [];
        i18nState.supportedLanguages = ['en', 'it'];
        vi.useFakeTimers();
        const promise = localeChoice(routeTo({ params: { locale: 'it' } }));
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return promise;
            })
            .then((result) => {
                expect(result).toBe(true);
                // Order matters: messages must be registered before the language is switched, or the
                // first render after the switch has no translations.
                expect(updateLocaleMock).toHaveBeenCalledWith('it', expect.any(Object));
                expect(changeLanguageMock).toHaveBeenCalledWith('it');
            });
    });

    it('redirects an unsupported locale to the default, preserving route name and query', () => {
        i18nState.supportedLanguages = ['en', 'it'];
        i18nState.defaultLocale = 'en';
        return localeChoice(
            routeTo({
                name: 'products',
                params: { locale: 'kl', id: '42' },
                query: { page: '2' }
            })
        ).then((result) => {
            // Dropping params or query here would silently lose the user's place on every
            // locale-less deep link.
            expect(result).toEqual({
                name: 'products',
                params: { locale: 'en', id: '42' },
                query: { page: '2' }
            });
        });
    });

    it('redirects when the route carries no locale at all', () => {
        i18nState.defaultLocale = 'it';
        return localeChoice(routeTo({ name: 'home', params: {} })).then((result) => {
            expect(result).toEqual({
                name: 'home',
                params: { locale: 'it' },
                query: {}
            });
        });
    });

    it('does not activate any language while redirecting', () => {
        i18nState.supportedLanguages = ['en'];
        return localeChoice(routeTo({ params: { locale: 'zz' } })).then(() => {
            expect(changeLanguageMock).not.toHaveBeenCalled();
            expect(updateLocaleMock).not.toHaveBeenCalled();
        });
    });
});

tests/cross-cutting/registry.spec.ts.source:
/**
 * Invariants every enabled module must satisfy, whichever modules those are.
 *
 * This is the shape a cross-cutting spec is allowed to take: it **iterates** the registry and
 * never **names** a domain. Delete `products` and this file keeps passing, testing one module
 * fewer — which is exactly what `docs/theory/modules.md` asks of a spec that lives outside a
 * module.
 *
 * The property is "every menu entry any module contributes points at a route that module
 * declares, and every route it declares is reachable" — not "products is in the menu and is
 * public". A hardcoded phrasing breaks when a domain is removed; this one does not.
 *
 * The failure it exists to catch is a silent one: a `navigation` entry naming a route that does
 * not exist renders a link that resolves to nothing. `vue-router` warns in the console and
 * carries on, so a human clicking around finds it and no gate does.
 */
import { describe, expect, it } from 'vitest';
import type { RouteRecordRaw } from 'vue-router';
import { enabledModules } from '@/modules';
import type { ITranslationDictionaries } from '@/infrastructure/i18n';
import { validateModules } from '@/kernel/registry';

/** Every route name a record tree declares, at any depth. */
const routeNamesOf = (routes: RouteRecordRaw[]): string[] =>
    routes.flatMap((route) => [
        ...(typeof route.name === 'string' ? [route.name] : []),
        ...routeNamesOf(route.children ?? [])
    ]);

const moduleCases = enabledModules.map((appModule) => [appModule.name, appModule] as const);

describe('the enabled registry', () => {
    it('is internally consistent — no duplicate name, no unknown or cyclic dependency', () => {
        expect(() => validateModules(enabledModules)).not.toThrow();
    });

    it('enables at least one module, so the sweeps below are not vacuously true', () => {
        expect(enabledModules.length).toBeGreaterThan(0);
    });

    it('declares every dependency as a module that is itself enabled', () => {
        const names = new Set(enabledModules.map(({ name }) => name));

        for (const { dependsOn = [] } of enabledModules)
            for (const dependency of dependsOn) expect(names).toContain(dependency);
    });
});

describe.each(moduleCases)('module %s', (_name, appModule) => {
    it('contributes navigation entries that point at routes it declares', () => {
        const declared = new Set(routeNamesOf(appModule.routes));

        for (const { name } of appModule.navigation ?? []) expect(declared).toContain(name);
    });

    it('gives every navigation entry an order, so it cannot silently sink to the bottom', () => {
        for (const entry of appModule.navigation ?? []) expect(entry.order).toBeTypeOf('number');
    });

    it('names every route it declares — the navigation and the guards address routes by name', () => {
        for (const route of appModule.routes) expect(typeof route.name).toBe('string');
    });
});

/**
 * Dictionary collisions.
 *
 * Nesting every key under its module (`products.list.page-title` rather than
 * `products-list-page.page-title`) would make a collision impossible by construction, but it
 * touches every `.vue` file and every JSON, and keys already carry a domain prefix by convention.
 * This catches the same failure at roughly none of the cost.
 *
 * The failure: dictionaries are DEEP-MERGED at boot, in registration order. If two modules declare
 * the same top-level key, the later one's entries win and the earlier one's copy vanishes. Nothing
 * throws. The page renders raw keys, and only a human reading the screen in that language notices.
 *
 * `navigation` is the deliberate exception — every module contributes its own `label-*` slice of
 * it, which is exactly why the merge has to be deep. So it is checked one level lower instead:
 * co-owning the namespace is fine, claiming the same entry inside it is not.
 */
const CO_OWNED_NAMESPACE = 'navigation';

/** Locale codes any enabled module ships, deduplicated. */
const localeCodes = [
    ...new Set(enabledModules.flatMap((appModule) => Object.keys(appModule.locales ?? {})))
];

/** Every contributor's dictionary for one locale, the shared one included, labelled by owner. */
const dictionariesFor = (
    locale: string
): Promise<{ owner: string; dictionary: ITranslationDictionaries }[]> =>
    Promise.all([
        (import(`@/locales/${locale}.json`) as Promise<{ default: ITranslationDictionaries }>).then(
            ({ default: dictionary }) => ({ owner: '<shared>', dictionary })
        ),
        ...enabledModules
            .filter((appModule) => appModule.locales?.[locale])
            .map((appModule) =>
                appModule.locales![locale]().then((dictionary) => ({
                    owner: appModule.name,
                    dictionary
                }))
            )
    ]);

/** key → the contributors that declare it, for anything declared more than once. */
const clashesIn = (entries: { owner: string; keys: string[] }[]): Record<string, string[]> => {
    const owners: Record<string, string[]> = {};

    for (const { owner, keys } of entries) for (const key of keys) (owners[key] ??= []).push(owner);

    return Object.fromEntries(
        Object.entries(owners).filter(([, contributors]) => contributors.length > 1)
    );
};

describe.each(localeCodes)('locale dictionaries — %s', (locale) => {
    it('gives every top-level namespace exactly one owner', () =>
        dictionariesFor(locale).then((loaded) => {
            const clashes = clashesIn(
                loaded.map(({ owner, dictionary }) => ({
                    owner,
                    keys: Object.keys(dictionary).filter((key) => key !== CO_OWNED_NAMESPACE)
                }))
            );

            // Named rather than counted: the message has to say WHICH namespace and WHO, or the
            // failure is a scavenger hunt through seven JSON files.
            expect(clashes).toEqual({});
        }));

    it(`gives every ${CO_OWNED_NAMESPACE} entry exactly one owner, though the namespace is shared`, () =>
        dictionariesFor(locale).then((loaded) => {
            const clashes = clashesIn(
                loaded.map(({ owner, dictionary }) => ({
                    owner,
                    keys: Object.keys(
                        (dictionary[CO_OWNED_NAMESPACE] as ITranslationDictionaries | undefined) ??
                            {}
                    )
                }))
            );

            expect(clashes).toEqual({});
        }));

    it('is shipped by every module, so no domain is untranslated in this language', () => {
        const missing = enabledModules
            .filter((appModule) => appModule.locales && !appModule.locales[locale])
            .map(({ name }) => name);

        expect(missing).toEqual([]);
    });
});

tests/unit/infrastructure/errors.spec.ts.source:
import { beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import { notifyErrorMessages, VUETIFY_INVALID_FIELD_SELECTOR } from '@/infrastructure/errors.ts';
import { loadLocale } from '@/infrastructure/i18n.ts';
import enMessages from '@/locales/en.json';

/**
 * The "nothing usable in the error" fallback is translated copy now, so the dictionary has to be
 * loaded or every such assertion would compare against a raw key.
 */
beforeAll(() => loadLocale('en'));

/**
 * The observability store is stubbed so the "reported to Faro" half of `notifyErrorMessages`
 * is observable: the real `captureException` is a deliberate no-op until Faro connects, so
 * against the real store every assertion about reporting would pass vacuously.
 */
const captureExceptionMock = vi.fn();
vi.mock('@/infrastructure/observability', () => ({
    useObservabilityStore: () => ({ captureException: captureExceptionMock })
}));

describe('notifyErrorMessages', () => {
    beforeEach(() => {
        setActivePinia(createPinia());
        vi.clearAllMocks();
    });

    it('shows the error message when it is a string', () => {
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, 'email already registered');
        expect(addMessage).toHaveBeenCalledWith('email already registered');
    });

    it('shows the message of an Error instance', () => {
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, new Error('network down'));
        expect(addMessage).toHaveBeenCalledWith('network down');
    });

    it('shows the message property of an error-like object', () => {
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, { message: 'Forbidden' });
        expect(addMessage).toHaveBeenCalledWith('Forbidden');
    });

    it('falls back to a generic message for unrecognized errors', () => {
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, 42);
        expect(addMessage).toHaveBeenCalledWith(enMessages['api-errors'].unknown);
    });

    // The `&& error` / `&& error.message` guards below each exist to stop an *empty* message
    // being shown to a user as if it were an explanation. They are individually invisible in a
    // review and individually easy to drop, so each falsy shape gets its own case.

    it('falls back rather than showing an empty string', () => {
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, '');
        expect(addMessage).toHaveBeenCalledWith(enMessages['api-errors'].unknown);
    });

    it('falls back rather than showing an Error with an empty message', () => {
        const addMessage = vi.fn();
        // eslint-disable-next-line unicorn/error-message -- the empty message is the input under test
        notifyErrorMessages(addMessage, new Error(''));
        expect(addMessage).toHaveBeenCalledWith(enMessages['api-errors'].unknown);
    });

    it('falls back rather than showing an error-like object with an empty message', () => {
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, { message: '' });
        expect(addMessage).toHaveBeenCalledWith(enMessages['api-errors'].unknown);
    });

    it('falls back when the message property is not a string', () => {
        // e.g. a parsed API body whose `message` is an array of validation errors — rendering
        // that raw would put "[object Object]" in front of a user.
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, { message: { nested: true } });
        expect(addMessage).toHaveBeenCalledWith(enMessages['api-errors'].unknown);
    });

    it('falls back for null without throwing', () => {
        // `typeof null === 'object'`, so the `error &&` guard is the only thing preventing a
        // TypeError here — and `null` is what an empty rejected body deserialises to.
        const addMessage = vi.fn();
        expect(() => notifyErrorMessages(addMessage, null)).not.toThrow();
        expect(addMessage).toHaveBeenCalledWith(enMessages['api-errors'].unknown);
    });

    it('reports the original value to observability, not the derived message', () => {
        // The user gets a readable string; telemetry must get the real thing, stack included,
        // or the report is worthless for debugging.
        const error = new Error('network down');

        notifyErrorMessages(vi.fn(), error);

        expect(captureExceptionMock).toHaveBeenCalledWith(error);
    });

    it('reports even when the message could not be derived', () => {
        // The fallback path is the one where telemetry matters most: nobody can act on
        // "Unknown error" without the underlying value.
        notifyErrorMessages(vi.fn(), 42);

        expect(captureExceptionMock).toHaveBeenCalledWith(42);
    });
});

/**
 * Renders Vuetify-shaped markup and returns what the selector picks out of it.
 */
const firstMatch = (html: string) => {
    const form = document.createElement('form');
    form.innerHTML = html;
    document.body.append(form);
    const found = form.querySelector<HTMLElement>(VUETIFY_INVALID_FIELD_SELECTOR);
    form.remove();
    return found;
};

describe('VUETIFY_INVALID_FIELD_SELECTOR', () => {
    /**
     * The focusing itself is `useStructureFormValidation`'s, and tested there. What belongs to
     * this repo is the selector: the toolkit's `[aria-invalid="true"]` default does not fit
     * Vuetify, where only the wrapper carries the error state. So these assert what the selector
     * finds in Vuetify-shaped markup, which is what breaks if Vuetify renames a class.
     */
    it('finds the input inside a field in error', () => {
        expect(firstMatch('<div class="v-input--error"><input id="target" /></div>')?.id).toBe(
            'target'
        );
    });

    it('finds the FIRST invalid field when several are in error', () => {
        // "first invalid field" is the accessibility contract; focusing the last would move the
        // user past the error they need to fix.
        expect(
            firstMatch(
                '<div class="v-input--error"><input id="first" /></div>' +
                    '<div class="v-input--error"><input id="second" /></div>'
            )?.id
        ).toBe('first');
    });

    it('ignores fields that are not in an error state', () => {
        expect(
            firstMatch(
                '<div><input id="valid" /></div>' +
                    '<div class="v-input--error"><input id="invalid" /></div>'
            )?.id
        ).toBe('invalid');
    });

    it('falls back to [tabindex] for controls with no native input', () => {
        // v-select and friends expose no focusable input/textarea/select of their own; without
        // the trailing selector they would be silently unreachable.
        expect(
            firstMatch('<div class="v-input--error"><div id="select" tabindex="0"></div></div>')?.id
        ).toBe('select');
    });

    it('covers textarea and select too', () => {
        expect(
            firstMatch('<div class="v-input--error"><textarea id="area"></textarea></div>')?.id
        ).toBe('area');
        expect(
            firstMatch('<div class="v-input--error"><select id="pick"></select></div>')?.id
        ).toBe('pick');
    });

    it('matches nothing when no field is in error', () => {
        expect(firstMatch('<div><input id="valid" /></div>')).toBeNull();
    });
});

